                "Гладким клинком в тюрьме кашу не сваришь! Но режешь ты знатно — айда выпотрошим пару жирных боссов на пару!");

            AddPair(dict, "gwen", "tidehunter",
                "Ох, великое небо... Господин Левиафан, вы такой громадный! Чтобы сшить вам парадный камзол, не хватит всех парусов Билджвотера!",
                "Парусов?! Не смей произносить при мне это слово — от белой парусины у меня сразу перед глазами всплывает наглая физиономия адмирала Кункки!",
