            AddPair(dict, "gwen", "gold_ship",
                "Какой великолепный алый мундир с золотыми эполетами и лентами! Сразу видно наряд, сшитый для стремительного полёта и праздника!",
                "А ТО! Это парадная броня непобедимого Золотого Корабля! А шляпа на макушке — секретный антенный ретранслятор связи с созвездием Морковки!",
