                "Я хорошо знаю печаль брошенных игрушек, запертых в темноте... Но пугать живых и гасить свет — совсем не способ согреть сердце.",
                "Бззт... Сердце в комплектацию эндоскелета 87-го года не входит! Но на сцене внизу мы с тобой устроим незабываемое ночное представление!");

            AddPair(dict, "gwen", "steve",
                "Удивительно, Стив! Я смотрю на вашу бирюзовую рубашку в упор и не вижу ни единого шва, ни одной складочки — сплошные ровные квадратики!",
