            AddPair(dict, "gwen", "vyper",
                "Ай-ай-ай, мисс Вайпер! Если так скользить на животе по острой каменной крошке, на вашем жилете скоро живого места не останется!",
                "Ха, да пёс с ним, с жилетом, куколка! В Нью-Йорке главное правило: кто ползёт ниже пулемётной очереди — тот доживает до получки!",
