            AddPair(dict, "enforcer", "medic",
                "Герберт Людвиг? Бортовой терминал выдал красную пометку: ваша врачебная лицензия аннулирована, а в графе «причина» — прочерк и крики.",
                "Аха-ха! Бюрократы вечно придираются из-за одного пропавшего скелета! Лучше скажите, голубчик: ваш щит проводит высокочастотный ток Убер-заряда?",
                "Энергетическая кромка экранирована, но перегрузки не пробовал. Если вздумаешь вшить мне лишний орган — применю слезоточивый газ.",
