            AddPair(dict, "enforcer", "reimu",
                "Гражданская одежда, открытые плечи и горсть бумажных полосок вместо бронежилета... Кто вообще допустил тебя в десантную капсулу?",
                "Эй, полегче с тоном, железный шкаф! Эти «бумажки» держат Великий Барьер Хакурей против таких ёкаев, которые твой щит на завтрак сжуют.",
