                "Оценил твои укрепления с прошлого вылета, «Гамма». Ториевые стены и эшелонированные турели — прямо по учебнику гарнизонной осады.",
                "[ТЕЛЕМЕТРИЯ СЕРПУЛО: ОДОБРЕНО. ВЫ КЛАССИФИЦИРОВАНЫ КАК ПОДВИЖНЫЙ ОТРАЖАЮЩИЙ БАСТИОН ПЕРВОЙ ЛИНИИ.]",
                "Подвижный бастион? Звучит получше, чем «ходячая мишень». Главное — настрой датчики турелей, чтобы не садили мне в затылок.",
