            AddPair(dict, "enforcer", "slark",
                "Беглец из особого изолятора Тёмного Рифа, вооружён самодельной заточкой... В моём секторе ты бы уже лежал лицом в палубу в наручниках.",
                "Хе-хе-хе, остынь, вертухай! Я свалил со дна океана из адамантовой клетки — неужто твоих жестяных браслетов испугаюсь?",
                "Пока мы на «Safe Travels», действует военная амнистия. Но замечу хоть одну вскрытую ячейку экипажа — вылетишь в шлюз без скафандра.",
                "Тьфу, нудный ты тип! Ладно, держи монстров на своём щите спереди, а я им тихонько почки сзади подрежу — честная сделка!");

            AddPair(dict, "enforcer", "tidehunter",
                "Впервые вижу пехотинца, который использует корабельный становой якорь вместо дубинки. Какая же у тебя нагрузка на грунт?",
                "Нагрузка как у морского цунами, человек в каске! Мой Панцирь Кракена крепче обшивки любого линкора этого выскочки Кункки!",
