                "Безумца?! Это называется «высокооплачиваемая разведка труднодоступных пещер»! Просто тормоза на лебёдке иногда клинит!",
                "Ха-ха, не оправдывайся! Сгоняй наверх и сбрось мне самую крупную дичь с обрыва — остальное мои клинки сделают красиво!");

            AddPair(dict, "scout", "w_arknights",
                "Э-э, нет! Стоять! Я этот хитрый прищур и красный мигающий брикет C4 за версту чую! Ты точь-в-точь наш Бурильщик перед посадкой в капсулу!",
                "Ой, какой пуганый гномик~ Неужели коллеги уже приучили тебя проверять потолок перед тем, как лететь туда на крюке-кошке?",
                "Трижды за прошлую неделю мне бороду пластидом подпалили «случайно»! Предупреждай за пять секунд, куда кидаешь свои карты, договорились?!",
                "Пять целых секунд?! Ладно-ладно, крикну «раз-два-три»... сразу после того, как нажму на детонатор, хи-хи-хи!");

            AddPair(dict, "scout", "gold_ship",
                "Спорим на золотой самородок, длинноногая: пока ты добежишь до дальнего утёса, я туда на крюке и пороховом дуплете слетаю туда и обратно!",
                "ВЫЗОВ ПРИНЯТ, КОРОТЫШКА! Золотой Корабль на последней прямой обгоняет звук, свет и твою бельевую верёвку с моторчиком!",
                "Бельевую верёвку?! Да эта титановая кошка вытаскивала меня из пасти пещерной пиявки! Готовься глотать пыль из-под моих подкованных сапог!",
                "ПОЛНЫЙ ВПЕРЁД! Кто прибежит к Телепорту вторым — покупает победителю ведро жареной якисобы и получает почётный дропкик!");

            AddPair(dict, "scout", "pushnoy",
                "Слышь, Саня, я всё спросить хотел: как твой перегруженный гитарный комбик бьёт молнией сильнее моей электрогранаты IFG?!",
                "А вот это, дорогой друг, классический резонанс Теслы и третий закон Ньютона! Кстати, как ты на дуплете от выстрела вверх улетаешь и руки не вывихиваешь?!",
                "Особый порох, крепкие дварфийские кости и ноль лишних вопросов к физике! Главное — вовремя крюком за скалу уцепиться перед землёй!",
                "ГЕНИАЛЬНО! На следующей высадке замеряем твою баллистическую траекторию под моё соло на двух бочках — наука будет в восторге!");

            AddPair(dict, "scout", "freddy",
                "Постой-ка, медведь... Ты реально думаешь напугать потомственного шахтёра с Хоксеса тем, что выключишь свет и пощёлкаешь челюстями в темноте?!",
                "Хар-хар-хар! Ни один ночной сторож не смеялся, когда гасли прожекторы и начинала играть моя музыкальная шкатулка!",
                "Пф-ф! У меня в подсумке ракетница с магниевыми осветилками на тысячу люмен! Щёлк под потолок — и светло как в полдень!",
                "Бззт... Осветительные приборы вне сметы Fazbear Entertainment запрещены правилами! Не смей портить мне драматический выход во мраке!");

            AddPair(dict, "scout", "steve",
                "Так, дай-ка пожать твою квадратную лапу, брат-шахтёр! Я как увидел, с какой скоростью ты киркой породу до алмазов пробиваешь, чуть слезу не пустил!",
                "У тебя тоже кирка ладная. Только странно, что камни у вас рассыпаются на круглые куски, а не ровными кубами по метру.",
                "Зато суть одна: копаем глубоко, бьём нечисть в потёмках и тащим золото домой! Крикнем вместе за всех горняков Вселенной — СКАЛА И КАМЕНЬ!",
                "Скала и Камень. Держи золотое яблоко в дорогу — в глубоких шахтах выручает почище зелья.");

            AddPair(dict, "scout", "jotaro",
                "Мать моя горная порода! Твой фиолетовый дух за секунду раскрошил каменного голема в мелкий щебень голыми кулаками! Ему бы у нас туннели пробивать!",
                "Star Platinum — не буровая установка, гном. Хотя точности ему хватит, чтобы достать золотую крупицу из цельной скалы не задев камень.",
                "Ого, да с такой реакцией ты и пещерную пиявку в темноте за миллисекунду перехватишь! Уважаю суровых профи!",
                "Ярэ-ярэ... А ты неплохо держишь воздух на этом крюке. Помечай стрелков на скалах — остальное сделаем мы со Стендом.");

            AddPair(dict, "scout", "vyper",
                "Гляди-ка, идеальная пара получается: я летаю под самыми облаками на тросе, а ты носишься брюхом по земле быстрее таракана!",
                "Эй, полегче про таракана, бородатый! Это фирменный манхэттенский слайд! Слушай, а правда, что у тебя в мешке настоящее необработанное золото?!",
                "Ещё какое настоящее — чистейший самородок! Только лапки-то придержи, рептилия: за кражу корпоративной руды Штаб шкуру спустит!",
                "Жадина! Ладно-ладно, возьму процентами с боссов на поверхности — я их болой в камень превращу, а ты кроши сверху в своё удовольствие!");

            AddPair(dict, "scout", "haze",
                "Говорят, ты чужие сны насквозь видишь, агент Хейз? Спорим, в моей голове кроме звона кирки и пены в кружке ничего не разглядишь!",
                "Напротив, Разведчик: твои сны удивительно яркие. Бескрайние золотые пещеры, верные братья по оружию... и какая-то легенда по имени Карл.",
                "...Эх, за Карла любой дварф без раздумий в пекло прыгнет. Умеешь ты за живое задеть, туманная леди.",
                "В моём ремесле редко встречаешь столь крепкий дух без тени предательства. Лети спокойно — прикрою тебя из дымки.");

            AddPair(dict, "scout", "dmc_trio",
                "Обрез в одной руке, рывки по воздуху без страховки, шуточки в лицо здоровенным тварям — да ты ж вылитый Разведчик, Данте, только без бороды!",
                "Ха! Прости, приятель, окладистая борода под мой алый плащ по стилю не вписывается, да и пиццу с сыром из усов вычёсывать замучаешься!",
                "Слабое оправдание, скажу я тебе! В бороде весь боевой авторитет и запас сухарей на чёрный день хранится!",
                "Ладно, уел! Зато по части стрельбы с двух рук в полёте мы с тобой точно сработаемся на ранг SSS — погнали проверим!");

            AddPair(dict, "scout", "sanabi",
                "Генерал! Я как увидел твой маятниковый разгон на стальном тросе через всё ущелье — аж каску снял! Вот это я понимаю — мастер крюка-кошки!",
                "Мари: Хи-хи, слышишь, пап? Коллега-верхолаз заценил твой армейский гарпун! — Генерал: У вашей пневматики отличная скорость возврата, боец.",
                "Моя лебёдка тянет по прямой к точке, зато ты на раскачке влетаешь во врага как бронебойный снаряд! Надо у наших технарей такой же трос выпросить!",
                "Генерал: Без кибернетического плеча отдачей вырвет сустав, не советую. — Мари: Лучше летайте парой на высадке — ни один титан голову поднять не успеет!");

            AddPair(dict, "m4a1", "medic",
                "Доктор Людвиг, благодарю за предложение осмотра, но тактическим куклам требуется ремонтный отсек и паяльная станция Персики, а не хирургия.",
                "Чепуха, фройляйн! Мой лечебный луч одинаково бодро сшивает плоть, титановые сервоприводы и даже ваши очаровательные голографические копии!",
                "Странно... Телеметрия подтверждает прирост мощности реактора при контакте с вашим лучом, хотя это противоречит всем законам физики.",
                "Законы физики — для врачей с лицензией! Подождите, пока я подам Убер-заряд прямо в конденсаторы вашей пушки «Юпитер» — вот будет фейерверк!");

            AddPair(dict, "m4a1", "aigis",
                "Айгис, ваши боевые показатели поразительны, но ещё удивительнее другое: в вашем голосе нет холодной отстранённости обычного ИИ.",
                "Мои друзья из отряда S.E.E.S. научили меня понимать человеческие чувства. А в твоём нейрооблаке я тоже ощущаю глубокую привязанность к близким.",
                "Когда-то я боялась ответственности, но ради сестёр из отряда AR и Командира научилась идти до конца. Мы с вами во многом похожи.",
                "Подтверждаю сходство! Значит, на этой планете у нас общая миссия: защитить каждого союзника и вернуться домой без потерь.");

            AddPair(dict, "m4a1", "reimu",
                "Мисс Хакурей, вы уже третий раз так пристально смотрите на мои автономные модули... Они мешают вашей траектории полёта?",
                "Ещё как мешают моему кошельку! Пока я лечу к одному сундуку на краю карты, твои четверо двойников уже пылесосят всю долину подчистую!",
                "Ох, простите! Сбор трофеев заложен в базовый протокол разведки... Но ведь всё найденное золото автоматически зачисляется в общий счёт отряда!",
                "В общий счёт — это хорошо, но в храме Хакурей учёт строгий! Пусть хотя бы один твой клон приносит блестящие монетки лично мне в руки.");

            AddPair(dict, "m4a1", "mindustry",
                "Блок управления «Гамма», мои тактические модули завершили разведку периметра. Ваши турели готовы принять целеуказание?",
                "[СИНХРОНИЗАЦИЯ СЕТИ: ВАШИ 4 ПРОЕКЦИИ DUMMY LINK ПОКАЗЫВАЮТ КПД СБОРА РЕСУРСОВ НА 340% ВЫШЕ ДРОНОВ «МОНО».]",
                "Мои проекции созданы для огневого манёвра, но в здешних условиях снабжение решает исход боя не меньше меткой стрельбы.",
                "[ПРОТОКОЛ КОАЛИЦИИ АКТИВИРОВАН: ОБЪЕДИНЯЮ РАДАР ЯДРА С ПРИЦЕЛОМ ВАШЕГО ОРУДИЯ «ЮПИТЕР». ОГОНЬ ПО ГОТОВНОСТИ.]");

            AddPair(dict, "m4a1", "slark",
                "Когда вы уходите в своё чёрное облако, Сларк, мои тепловизоры и радар сети теряют вас полностью — точно как элитных лазутчиков «Сангвис Ферри».",
                "Хе-хе, против тюремной смекалки Тёмного Рифа любая электроника слепнет! Зато с твоими четырьмя куклами отвлекать ротозеев — одно удовольствие!",
                "Главное — подавайте сигнал перед прыжком в тыл противника, чтобы вы не попали под линию разряда моей рельсовой пушки.",
                "Уж зелёное сияние с твоего плеча я и под водой замечу! Выжигай им панцири с фронта, командирша, а я дорежу подранков!");

            AddPair(dict, "m4a1", "tidehunter",
                "Расчёт баллистики показывает, что стандартный патрон 5.56 почти не пробивает чешую класса «Панцирь Кракена». Серьёзная природная защита.",
                "А то! Об мою спину ломались тараны лучших фрегатов Кункки! Твои трещотки для меня — что мелкая морская галька в прибой!",
                "Именно поэтому для сверхтяжёлых целей у меня за плечом сложен портативный «Юпитер». Надеюсь, местные титаны не крепче морских чудовищ.",
                "Ого, вот эта зелёная молния внушает уважение! Бей ею сразу после того, как мои щупальца подбросят врагов к облакам!");

            AddPair(dict, "m4a1", "freeman",
                "Доктор Фриман, излучение вашей Тау-пушки на стенде удивительно напоминает экспериментальные ускорители на коллапс-жидкости из нашего мира.",
                "... *заинтересованно подходит ближе, поправляет очки и с научным восхищением осматривает складной кожух пушки «Юпитер»* [КОСТЮМ HEV: Зафиксирован высокоэнергетический рельсовый излучатель.]",
                "Будьте осторожны у дульного среза в бою — при полном залпе тепловой выброс сжигает всё на линии выстрела.",
                "... *понимающе кивает — сам не раз улетал от перегрузки Гаусса — и показывает большой палец в знак одобрения*");

            AddPair(dict, "m4a1", "dante",
                "Исполнительный Менеджер Данте... Глядя, как вы ведёте свой отряд сквозь боль, я невольно вспоминаю нашего Командира в самые тяжёлые дни.",
                "<Тик-так... тик!> (Правда?! Хотя поспорю, твой Командир командует дисциплинированными бойцами, а не двенадцатью буйными психопатами в автобусе!)",
                "На самом деле сёстры из моего отряда — особенно SOPMOD II — тоже умеют устроить на базе полный кавардак... Но я всё равно дорожу каждой из них.",
                "<Тик... так...> (Эх, да и я к своим охламонам уже прикипел. Береги своё ядро внизу, M4A1 — а живых я, если что, подниму.)");

            AddPair(dict, "m4a1", "cheburashka",
                "Удивительное существо... Ни одного совпадения в базах фауны, но уровень угрозы — абсолютный ноль. Если бы SOPMOD увидела твои уши, уже не отпустила бы.",
                "Ой, а у вас четверо близняшек в одинаковой форме! Давайте я поделю большой апельсин ровно на пять долек, чтобы никому не было обидно!",
                "Спасибо, Чебурашка, но вкусовые сенсоры установлены только в моём основном корпусе — остальные четыре фигуры лишь боевые проекции.",
                "Значит, вам достанется целый апельсин! А если на вас нападёт большой каменный монстр, мы с Геной сразу встанем рядом!");

            AddPair(dict, "m4a1", "ahri",
                "Мисс Ари, когда ваши хвосты вспыхивают голубым духовным огнём, в моём нейрооблаке возникают странные помехи... словно эхо чужих снов.",
                "Прости, милая, я не пыталась подглядывать~ Просто внутри твоей стальной оболочки светится память, удивительно похожая на живую человеческую душу.",
                "...Персика создала мою матрицу на основе особого слепка, о котором я сама знаю не всё. Иногда эти осколки воспоминаний кажутся слишком тяжёлыми.",
                "Не бойся прошлого, храбрый командир. Важно лишь то, ради кого твоё сердце бьётся здесь и сейчас~");

            AddPair(dict, "m4a1", "lappland",
                "Кристаллы на вашей коже фонят почти как зоны заражения коллапс-излучением... Вам точно не требуется медицинская стабилизация перед боем?",
                "Ха! Моя орипатия — это лишь приправа к хорошему фехтованию, куколка! А вот твоя манера стрелять сразу с пяти позиций выглядит весьма занятно.",
                "Перекрёстный огонь экономит боеприпасы и не даёт противнику сблизиться со строем.",
                "Какая холодная расчётливость! Только оставь пару крупных зверей для моих клинков, иначе я заскучаю раньше третьего этапа!");

            AddPair(dict, "m4a1", "w_arknights",
                "Мисс W, ваши методы минирования до боли напоминают мне почерк AR-15 и необузданный нрав SOPMOD в одном лице... только ещё более безрассудный.",
                "Оу, приму за изысканный комплимент! Кстати, подружка, я заглянула под чехол у тебя за спиной — вот это карманная пушечка! Какой калибр?!",
                "Портативная артиллерийская система «Юпитер» модификации MOD3. И очень прошу: не клейте к её батарее свои карты с C4 «ради усиления».",
                "Тц, какая ты серьёзная булочка с корицей! Ладно, не трону твою игрушку — просто устроим соревнование, чей взрыв красивее накроет босса~");

            AddPair(dict, "m4a1", "gold_ship",
                "Невероятно... Мой баллистический вычислитель выдал критическую ошибку прогноза, пытаясь рассчитать траекторию вашего бега на полигоне!",
                "АХА-ХА! Ни один суперкомпьютер во Вселенной не предскажет следующий шаг Голд Шип, потому что я и сама его придумываю за секунду до прыжка!",
                "Вы только что пробежали по стене боком, кинули корабельный якорь и ударили мишень двумя ногами в падении... В каком уставе описана такая тактика?!",
                "В уставе Золотого Корабля! Строй своих четверых клонов на дорожку — бежим эстафету четыре по четыреста вокруг Телепорта!");

            AddPair(dict, "m4a1", "pushnoy",
                "Господин Пушной, с точки зрения прикладной физики ваша способность генерировать шаровые молнии гитарным звукоснимателем не поддаётся анализу.",
                "Зато твоя складная рельсовая гаубица «Юпитер» — чистейшая классика силы Лоренца и электромагнитного разгона плазмы! Сколько мегаджоулей на выходе?!",
                "Точные спецификации IOP засекречены, но для сквозного пробития бронированного шагохода или каменного титана хватает одного импульса.",
                "ВОТ ЭТО НАУКА! Давай на высадке синхронизируем залп: ты даёшь изумрудный луч, а я бью аккорд через катушку Теслы — проверим интерференцию!");

            AddPair(dict, "m4a1", "freddy",
                "Сканирование завершено... Корпус образца 1980-х годов, примитивные сервоприводы без нейрооблака, но внутри фиксируется аномальный остаточный сигнал.",
                "Хар-хар-хар! Современные высокотехнологичные куклы так любят хвастаться процессорами, пока в полночь не отключится внешний генератор!",
