            AddPair(dict, "tidehunter", "freeman",
                "Эй ты, в рыжем панцире! Подозрительно молчишь... Уж не водолаз-диверсант ли ты с флагмана проклятого адмирала Кункки?!",
                "... *уверенно качает головой, указывает на эмблему «лямбды» на груди и Грави-пушкой аккуратно придвигает Левиафану ящик армейских пайков* [КОСТЮМ HEV: Обнаружена разумная глубоководная форма жизни. Рекомендована дипломатия.]",
                "Ого! Консервы без всякой болтовни — да ты самый толковый сухопутный малый на этом корыте! Ещё бы моржа вяленого туда...",
