            AddPair(dict, "tidehunter", "dante",
                "Р-Р-АРГХ! Опять этот звон корабельной склянки! Клянусь Маэлроном, у меня от часов перед глазами призрачный флот Кункки встаёт!",
                "<Тик-так-тик-так!> (Тише, тише, пожалуйста, опустите якорь! Я не склянка и никакого Кункку в глаза не видел, я менеджер автобуса!)",
                "Автобуса?.. Ах да, сухопутная повозка без парусов и киля! Говорят, ты умеешь поднимать павших моряков обратно в строй?",
