                "Хрум-хрум... Хм! Сочнее морских ежей! А этот зелёный господин в шляпе позади тебя — тоже из морских рептилий?",
                "Это мой друг Крокодил Гена! Он вообще-то в зоопарке работал, но если монстры начнут хулиганить — мы вместе дадим им отпор!");

            AddPair(dict, "tidehunter", "ahri",
                "Даже не пытайся строить мне глазки, девятихвостая! О мой Панцирь Кракена разбивались даже чары самой Наги Сирены!",
                "Хи-хи, да я и не собиралась, большой морской ворчун~ Просто заглянула в твою память, а там сплошная селёдка и один бородатый капитан!",
                "НЕ СМЕЙ ПРОИЗНОСИТЬ ИМЯ ЭТОГО ПРОЙДОХИ КУНККИ! Как вспомню его ром и торренты — плавники сами в кулак сжимаются!",
