            AddPair(dict, "tidehunter", "lappland",
                "Чего кружишь вокруг меня и облизываешься, белая псина? Мою чешую твоими тонкими зубочистками три дня пилить будешь!",
                "Аха-ха! Никогда ещё не разделывала живого морского колосса в сиракузском стиле! Интересно, под твоим панцирем кровь солёная?",
