                "На целом призрачном флоте, будь он трижды проклят Бездной! Эх, мне бы десяток твоих липких бомб ему под киль...",
                "По рукам, зелёный! Внизу репетируем комбо: ты подбрасываешь всю ораву щупальцами в воздух, а я взрываю их ещё до приземления~");

            AddPair(dict, "tidehunter", "gold_ship",
                "Постой-ка... Ты зовёшься «Золотой Корабль» И таскаешь за спиной настоящий чугунный якорь?! Да кто ты, во имя Маэлрона, такая?!",
                "Я непобедимая легенда скачек Голд Шип! А якорь — лучший снаряд для утренней разминки и точного броска по вредным тренерам!",
                "БУА-ХА-ХА! Впервые в жизни вижу «корабль», который мне не хочется утопить! Бросок у тебя знатный, хоть хват цепи и странный!",
                "Тогда организуем клуб любителей тяжёлого железа! На счёт «три» кидаем оба якоря в первого попавшегося босса — РАЗ, ДВА, ТРИ!");

            AddPair(dict, "tidehunter", "pushnoy",
                "Твоя гремящая доска со струнами ревёт прямо как разлом Марианской впадины в шторм! Уважаю такой грохот, человек!",
                "Ха-ха, спасибо, старина! Это дроп-ре на ламповом перегрузе! Слушай, а с точки зрения физики — откуда из-под сухого камня лезут твои гигантские щупальца?!",
                "Куда ступит копыто чемпиона Маэлрона — там сама Бездна прорывает земную твердь! Никакая суша нам не указ!",
                "Межпространственная гидродинамика через ударный резонанс стопы! Друзья, если мы совпадём в такт на припеве — планета расколется пополам!");

            AddPair(dict, "tidehunter", "freddy",
                "Фу-у, понюхал тебя с голодухи — а внутри одни пружины, машинное масло и пыльный плюш! Даже медуза с мелководья нажористее!",
