                "Хар-хар-хар... Обещаю, до шести утра он из бухты без повода не выбежит. Разве что монстры забудут проверить камеры.");

            AddPair(dict, "tidehunter", "steve",
                "Эй, рудокоп с квадратной головой! Что это за голубой трезубец у тебя за поясом светится? Пахнет древним океанским чародейством!",
                "Сам утопленника в океане выбил. На нём чары «Тягун» для полёта в дождь и «Пронзатель V» — повышенный урон по любым морским тварям.",
                "...П-по морским тварям, говоришь?! Ты это... смотри в дождливую погоду на Petrichor V в мою сторону этим вилами не размахивай!",
