            AddPair(dict, "tidehunter", "jotaro",
                "Смелый ты человек — подошёл к Левиафану на шаг и даже глазом не моргнул! Моряк или очередной охотник за китами?",
                "Океанолог. Такая толщина роговых щитков на спине позволяет гасить кинетический удар торпеды... Потрясающий реликтовый образец.",
                "Ха! Сразу видно учёного мужа, который понимает толк в Панцире Кракена, а не палит из пушек без разбору, как треклятый Кункка!",
