            AddPair(dict, "tidehunter", "haze",
                "От твоей жёлтой дымки у меня веки тяжелеют, будто я снова лёг в спячку на дне впадины... Убери своё колдовство, женщина!",
                "Прошу прощения. Просто разум древнего исполина так глубок, что даже лёгкое касание Песочного Человека поднимает в нём шторм.",
