            AddPair(dict, "tidehunter", "sanabi",
                "Гляжу на твою стальную руку с цепью, солдат, и уважаю! Хороший крюк в бою почти так же надёжен, как добрый адмиралтейский якорь!",
                "Генерал: Армейский гарпун рассчитан на скорость, а не на тоннаж. — Мари: Ого, дяденька-рыба, а дадите мне разок крутануть ваш якорь?!",
                "БУА-ХА-ХА! Подрасти сперва да съешь пару китов, малявка! Зато с моего плеча тебе всю долину как с грот-мачты видно будет!",
