            AddPair(dict, "freeman", "dante",
                "... *подходит с кружкой остывшего кофе, поправляет очки и с научным любопытством изучает пылающий циферблат* [КОСТЮМ HEV: Зафиксировано хроно-термическое излучение неустановленной природы.]",
                "<Тик-так?! Тик-так!> (Эй, полегче со сканером, док! На мне кофе не разогревают, и монтировкой часовой механизм тоже не чинят!)",
                "... *понимающе вздыхает, показывает на потёртый бейдж сектора «Аномальные материалы» и сочувственно хлопает Менеджера по плечу*",
