            AddPair(dict, "freeman", "cheburashka",
                "... *рефлекторно вскидывает монтировку при виде прыгающего из ящика пушистого силуэта, но замирает на замахе* [КОСТЮМ HEV: Внимание — объект не является хедкрабом. Угроза нулевая.]",
