            AddPair(dict, "freeman", "ahri",
                "... *невозмутимо протирает линзы очков платочком, совершенно игнорируя танцующие вокруг розовые искры* [КОСТЮМ HEV: Попытка психотропного гипноза отражена. Пульс в норме.]",
