            AddPair(dict, "freeman", "w_arknights",
                "... *замечает мигающий красный диод под переборкой, аккуратно срывает заряд C4 лучом Грави-пушки и протягивает его хозяйке* [КОСТЮМ HEV: Взрывное устройство обезврежено.]",
                "Эй-эй, ну зачем же портить сюрприз?! Хотя... слушай, а ловко ты снял мой «Валет Червей», даже датчик наклона не пискнул!",
                "... *крутит взрывчатку в гравитационном захвате и кивком показывает вниз на иллюминатор с планетой, предлагая метнуть заряд как снаряд*",
