            AddPair(dict, "freeman", "gold_ship",
                "... *замеряет взглядом траекторию серебристой бегуньи, пролетающей коридор длинными скачками* [КОСТЮМ HEV: Модуль длинных прыжков распознал родственную кинематику.]",
                "Ого! Мне ребята со склада рассказали, что ты умеешь разгоняться спиной вперёд до сверхзвука на одной отдаче! Коллега по распрыжке!",
