                "... *подходит к запотевшему иллюминатору и пальцем выводит на стекле уравнение распада резонансного кристалла* [КОСТЮМ HEV: Обнаружен дипломированный физик. Режим научного обмена.]",
                "Стоп-стоп-стоп... Доктор Гордон Фриман?! Живая легенда МТИ! Подожди, во втором слагаемом поправка на антимасс-спектрометр — ну конечно!",
