            AddPair(dict, "freeman", "steve",
                "... *протягивает вперёд закалённую в сотнях боёв красную монтировку, приветствуя коллегу по ручному труду* [КОСТЮМ HEV: Зафиксирован аномально плотный кубический инструмент.]",
                "Узнаю надёжный рычаг. Ломаешь деревянные ящики с одного удара? Уважаю. Хочешь, наковальней наложу на твою фомку «Прочность III»?",
